create table if not exists public.daily_learn_sessions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,lesson_slug text not null,area_key text,topic_slug text,correct_count integer not null default 0,total_count integer not null default 0,completed_at timestamptz,created_at timestamptz not null default now());alter table public.daily_learn_sessions enable row level security;create policy "daily_learn_own" on public.daily_learn_sessions for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
